import { Queue } from '../src/queue/client.js'; import { readConfig } from '../src/config.js'; const id = process.argv[2]; if (!id) throw new Error('Usage: npm run job:get -- <job-id>'); const queue = new Queue(readConfig()); const { data, error } = await queue.db.from('pipeline_jobs').select('*,pipeline_job_events(*)').eq('id', id).single(); if (error) throw error; console.log(JSON.stringify(data, null, 2));
